/** The preset package a consumer installs. */
export const CPP_PRESET_DIRECTORY = "node_modules/cpp-config-avi12";

/** The repo's own exemptions, options and compile database source, at the repo root. */
export const CPP_LOCAL_FILE = "avi12-cpp.local.json";

const GENERATED_BANNER =
  "# Generated by avi12-lint cpp-config from cpp-config-avi12 and avi12-cpp.local.json; do not edit";
const LOCAL_KEYS = new Set(["format", "tidy", "sources", "database"]);
const TIDY_LOCAL_KEYS = new Set([
  "enable",
  "disable",
  "options",
  "optionReasons",
  "directories",
  "headerFilterRegex",
  "warningsAsErrors"
]);
const PLAIN_SCALAR = /^[A-Za-z_][A-Za-z0-9_.-]*$/;

function scalar(value) {
  const isPlain = typeof value !== "string" || PLAIN_SCALAR.test(value);
  return isPlain ? String(value) : `'${value.replaceAll("'", "''")}'`;
}

function renderFormat(format) {
  const lines = [GENERATED_BANNER];
  for (const [key, value] of Object.entries(format)) {
    const isNested = typeof value === "object" && value !== null;
    if (!isNested) {
      lines.push(`${key}: ${scalar(value)}`);
      continue;
    }

    lines.push(`${key}:`);
    for (const [nestedKey, nestedValue] of Object.entries(value)) {
      lines.push(`  ${nestedKey}: ${scalar(nestedValue)}`);
    }
  }

  return `${lines.join("\n")}\n`;
}

function renderTidy({ checks, disabled, options, optionReasons, headerFilterRegex, warningsAsErrors }) {
  const entries = ["-*", ...checks, ...Object.keys(disabled).map(check => `-${check}`)];
  const checkLines = entries.map((entry, index) => `  ${entry}${index === entries.length - 1 ? "" : ","}`);
  const reasonLines = Object.entries(disabled).map(([check, reason]) => `#   ${check}: ${reason}`);
  const optionLines = Object.entries(optionReasons).map(([key, reason]) => `#   ${key}: ${reason}`);
  return `${[
    GENERATED_BANNER,
    ...(reasonLines.length > 0 ? ["# Checks that are off, and why:", ...reasonLines] : []),
    ...(optionLines.length > 0 ? ["# Options this repo changes, and why:", ...optionLines] : []),
    "Checks: >",
    ...checkLines,
    `HeaderFilterRegex: ${scalar(headerFilterRegex)}`,
    `WarningsAsErrors: ${scalar(warningsAsErrors)}`,
    "FormatStyle: file",
    "CheckOptions:",
    ...Object.entries(options).map(([key, value]) => `  ${key}: ${scalar(String(value))}`)
  ].join("\n")}\n`;
}

function renderDirectoryTidy({ disable, options, optionReasons }) {
  const reasonLines = Object.entries(disable).map(([check, reason]) => `#   ${check}: ${reason}`);
  const optionLines = Object.entries(optionReasons).map(([key, reason]) => `#   ${key}: ${reason}`);
  const off = Object.keys(disable).map(check => `-${check}`);
  return `${[
    GENERATED_BANNER,
    ...(reasonLines.length > 0 ? ["# Checks that are off in this folder, and why:", ...reasonLines] : []),
    ...(optionLines.length > 0 ? ["# Options this folder changes, and why:", ...optionLines] : []),
    "InheritParentConfig: true",
    ...(off.length > 0 ? [`Checks: ${scalar(off.join(","))}`] : []),
    ...(Object.keys(options).length > 0
      ? ["CheckOptions:", ...Object.entries(options).map(([key, value]) => `  ${key}: ${scalar(String(value))}`)]
      : [])
  ].join("\n")}\n`;
}

function validateDirectories(directories) {
  const problems = [];
  for (const [directory, config] of Object.entries(directories)) {
    for (const [check, reason] of Object.entries(config.disable ?? {})) {
      const isReasoned = typeof reason === "string" && reason.trim() !== "";
      if (!isReasoned) {
        problems.push(`${CPP_LOCAL_FILE}: tidy.directories "${directory}" disable "${check}" needs a reason`);
      }
    }

    for (const key of Object.keys(config.options ?? {})) {
      const reason = config.optionReasons?.[key];
      const isReasoned = typeof reason === "string" && reason.trim() !== "";
      if (!isReasoned) {
        problems.push(`${CPP_LOCAL_FILE}: tidy.directories "${directory}" option "${key}" needs a reason`);
      }
    }
  }

  return problems;
}

function validateLocal(local) {
  const problems = [];
  for (const key of Object.keys(local)) {
    if (!LOCAL_KEYS.has(key)) {
      problems.push(`${CPP_LOCAL_FILE}: unknown key "${key}"`);
    }
  }

  for (const key of Object.keys(local.tidy ?? {})) {
    if (!TIDY_LOCAL_KEYS.has(key)) {
      problems.push(`${CPP_LOCAL_FILE}: unknown key "tidy.${key}"`);
    }
  }

  for (const [check, reason] of Object.entries(local.tidy?.disable ?? {})) {
    const isReasoned = typeof reason === "string" && reason.trim() !== "";
    if (!isReasoned) {
      problems.push(`${CPP_LOCAL_FILE}: tidy.disable "${check}" needs a reason`);
    }
  }

  for (const key of Object.keys(local.tidy?.options ?? {})) {
    const reason = local.tidy?.optionReasons?.[key];
    const isReasoned = typeof reason === "string" && reason.trim() !== "";
    if (!isReasoned) {
      problems.push(`${CPP_LOCAL_FILE}: tidy.options "${key}" needs a reason in tidy.optionReasons`);
    }
  }

  return [...problems, ...validateDirectories(local.tidy?.directories ?? {})];
}

/**
 * Works out the `.clang-format` and `.clang-tidy` text `avi12-lint cpp-config` writes: the preset (`{ format, tidy }`,
 * the parsed `format.json` and `tidy.json`) merged with the repo's local file (parsed `avi12-cpp.local.json`, or
 * `{}`). `local.format` sets or (with `null`) removes a clang-format key; `local.tidy` adds checks (`enable`),
 * switches checks off with a reason (`disable`, a name to reason map), sets `options` (each with its reason in
 * `optionReasons`), and replaces
 * `headerFilterRegex` and `warningsAsErrors`, and `directories` (a folder to `{ disable, options, optionReasons }`)
 * writes a `.clang-tidy` in that folder that inherits the root one and changes only what it names. Returns `{ files: Map<name, text>, problems }`. Pure.
 */
export function planCppConfig({ preset, local = {} }) {
  const problems = validateLocal(local);
  const format = { ...preset.format };
  for (const [key, value] of Object.entries(local.format ?? {})) {
    if (value === null) {
      delete format[key];
    } else {
      format[key] = value;
    }
  }

  const tidy = local.tidy ?? {};
  const added = tidy.enable ?? [];
  const disabled = {
    ...preset.tidy.disable,
    ...tidy.disable
  };
  for (const check of added) {
    delete disabled[check];
  }

  const checks = [...new Set([...preset.tidy.enable, ...added])];
  const files = new Map([
    [".clang-format", renderFormat(format)],
    [
      ".clang-tidy",
      renderTidy({
        checks,
        disabled,
        options: {
          ...preset.tidy.options,
          ...tidy.options
        },
        optionReasons: tidy.optionReasons ?? {},
        headerFilterRegex: tidy.headerFilterRegex ?? preset.tidy.headerFilterRegex,
        warningsAsErrors: tidy.warningsAsErrors ?? preset.tidy.warningsAsErrors
      })
    ]
  ]);
  for (const [directory, config] of Object.entries(tidy.directories ?? {})) {
    files.set(
      `${directory}/.clang-tidy`,
      renderDirectoryTidy({
        disable: config.disable ?? {},
        options: config.options ?? {},
        optionReasons: config.optionReasons ?? {}
      })
    );
  }

  return {
    files,
    problems
  };
}

/** The paths whose current text (`existing`, a Map; a missing file is undefined) differs from what is wanted. */
export function staleCppFiles({ files, existing }) {
  return [...files].filter(([path, text]) => existing.get(path) !== text).map(([path]) => path);
}
